ons.show',$item->id,false)}}"><i class="fa fa-eye"></i></a><a class="action print" title="Print" target="_blank" href="{{route('admin.hrms.jobapplications.print',$item->id,false)}}"><i class="fa fa-print"></i></a><a class="action edit" title="Edit" href="{{route('admin.hrms.jobapplications.edit',$item->id,false)}}"><i class="fa fa-pencil"></i></a><form class="inline" method="POST" action="{{route('admin.hrms.jobapplications.destroy',$item->id,false)}}" onsubmit="return confirm('Are you sure you want to delete this job application?')">@csrf @method('DELETE')<button class="action delete" title="Delete"><i class="fa fa-times"></i></button></form></td></tr>@empty<tr><td colspan="7">No job applications found</td></tr>@endforelse</tbody></table><div class="job-app-count">Records: {{$applications->count() ? 1 : 0}} to {{$applications->count()}} of {{$applications->count()}}</div></div></section>
