@push('scripts')<script>
const readonly=@json($viewMode), degrees=@json($degreeLevels), oldQualifications=@json($qualifications), oldJobs=@json($previousJobs), oldExperiences=@json($experiences);let qi=0,ji=0,ei=0;
function esc(v){return String(v??'').replaceAll('&','&amp;').replaceAll('"','&quot;').replaceAll('<','&lt;').replaceAll('>','&gt;')}
function addQualification(data={},idx=qi){const b=document.getElementById('qualificationTableBody'),r=document.createElement('tr');r.id='q-'+idx;let opts='<option value="">-- Select Level --</option>'+degrees.map(x=>`<option ${data.level===x?'selected':''}>${x}</option>`).join('');r.innerHTML=`<td>${idx+1}</td><td><select name="qualifications[${idx}][level]" ${readonly?'disabled':''}>${opts}</select></td><td><input name="qualifications[${idx}][subjects]" value="${esc(data.subjects)}" ${readonly?'readonly':''}></td><td><input name="qualifications[${idx}][institute]" value="${esc(data.institute)}" ${readonly?'readonly':''}></td><td><input name="qualifications[${idx}][session]" value="${esc(data.session)}" ${readonly?'readonly':''}></td><td><input name="qualifications[${idx}][grade]" value="${esc(data.grade)}" ${readonly?'readonly':''}></td><td><input type="number" name="qualifications[${idx}][marks]" value="${esc(data.marks)}" ${readonly?'readonly':''}></td><td><input name="qualifications[${idx}][office_use]" value="${esc(data.office_use)}" ${readonly?'readonly':''}></td><td>${readonly?'':'<button type="button" class="action delete" onclick="document.getElementById(\'q-'+idx+'\').remove()">×</button>'}</td>`;b.appendChild(r);qi=Math.max(qi,idx+1)}
function addPreviousJob(data={},idx=ji){const b=document.getElementById('previousJobsTableBody'),r=document.createElement('tr');r.id='j-'+idx;r.innerHTML=`<td>${idx+1}</td><td><input name="previous_jobs[${idx}][organization]" value="${esc(data.organization)}" ${readonly?'readonly':''}></td><td><input name="previous_jobs[${idx}][designation]" value="${esc(data.designation)}" ${readonly?'readonly':''}></td><td><input name="previous_jobs[${idx}][duration]" value="${esc(data.duration)}" ${readonly?'readonly':''}></td><td><textarea name="previous_jobs[${idx}][responsibilities]" ${readonly?'readonly':''}>${esc(data.responsibilities)}</textarea></td><td>${readonly?'':'<button type="button" class="action delete" onclick="document.getElementById(\'j-'+idx+'\').remove()">×</button>'}</td>`;b.appendChild(r);ji=Math.max(ji,idx+1)}
function addExperience(data={},idx=ei){const b=document.getElementById('experienceContainer'),d=document.createElement('div');d.className='experience-entry';d.id='e-'+idx;const f=(key,label)=>`<div><label>${label}</label><input name="recent_experience[${idx}][${key}]" value="${esc(data[key])}" ${readonly?'readonly':''}></div>`;d.innerHTML=`<div class="panel-head"><b>Experience Entry #${idx+1}</b>${readonly?'':'<button type="button" class="button delete" onclick="document.getElementById(\'e-'+idx+'\').remove()">Delete</button>'}</div><div class="experience-grid">${f('company','School/Organization/Company')}${f('address','Address')}${f('phone','Phone No.')}${f('joined_as','Joined As')}${f('left_as','Left As')}${f('reason_to_leave','Reason To Leave')}${f('salary','Salary')}${f('reporting_to','Reporting to')}</div>`;b.appendChild(d);ei=Math.max(ei,idx+1)}
function formatCNIC(i){let v=i.value.replace(/\D/g,'').slice(0,13);if(v.length>5)v=v.slice(0,5)+'-'+v.slice(5);if(v.length>13)v=v.slice(0,13)+'-'+v.slice(13);i.value=v}function formatPhone(i){let v=i.value.replace(/\D/g,'').slice(0,11);if(v.length>4)v=v.slice(0,4)+'-'+v.slice(4);i.value=v}
document.addEventListener('DOMContentLoaded',()=>{oldQualifications.forEach((x,i)=>addQualification(x,i));oldJobs.forEach((x,i)=>addPreviousJob(x,i));oldExperiences.forEach((x,i)=>addExperience(x,i));if(!readonly){if(!oldQualifications.length)addQualification();if(!oldJobs.length)addPreviousJob();if(!oldExperiences.length)addExperience()}const p=document.getElementById('position_applied');if(p)p.addEventListener('change',()=>fetch(@json(route('admin.hrms.jobapplications.job-details',absolute:false)),{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content,'Accept':'application/json'},body:JSON.stringify({position:p.value})}).then(r=>r.json()).then(d=>document.querySelector('[name=min_salary_acceptable]').value=d.salary||''));document.querySelectorAll('.status-select').forEach(s=>s.addEventListener('change',()=>fetch(@json(url('/admin/hrms/jobapplications')).replace(/\/$/,'')+'/'+s.dataset.id+'/status',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content,'Accept':'application/json'},body:JSON.stringify({status:s.value})}).then(r=>r.json()).then(d=>{if(!d.success)alert('Failed to update status')})))})
</script>@endpush
@push('scripts')
<script>document.addEventListener('DOMContentLoaded',function(){const search=document.getElementById('job_app_search');if(!search)return;search.addEventListener('input',function(){const term=this.value.toLowerCase().trim();document.querySelectorAll('#job_app_table .job-app-row').forEach(function(row){row.style.display=row.textContent.toLowerCase().includes(term)?'':'none'})})});</script>
